test:
graph = VersionedSocialGraph()
bad_calls = [
    lambda: graph.follow('a', 'a'),
    lambda: graph.follow(1, 'a'),
    lambda: graph.is_following('a', 'b', -1),
    lambda: graph.is_following('a', 'b', 1),
]
for call in bad_calls:
    try:
        call()
        assert False, 'expected ValueError'
    except ValueError:
        pass
